        url: `${BASE_URL}/ko/꿈해몽/${encodeURIComponent(koreanSlug)}`,
        lastModified: new Date(),
        priority: 0.9,
      },
      {
        url: `${BASE_URL}/en/dream/${slug}`,
        lastModified: new Date(),
        priority: 0.8,
      }
    );
  }

  return entries;
}

